"""Lazy, composable iterable specifications for glom."""

import itertools

from boltons.iterutils import chunked_iter, unique_iter, windowed_iter

from .core import (T, SKIP, STOP, Path, TargetRegistry, glom, _MISSING)


def _iterate(target, scope):
    handler = scope[TargetRegistry].get_handler('iterate', target,
                                                path=scope[Path])
    return iter(handler(target))


def _map(iterator, spec, scope, sentinel):
    for index, value in enumerate(iterator):
        child = scope.new_child({Path: scope[Path] + [index]})
        result = scope[glom](value, spec, child)
        if result is sentinel or result is STOP:
            break
        if result is not SKIP:
            yield result


def _predicate(spec, scope):
    def predicate(value):
        result = scope[glom](value, spec, scope)
        return result is not SKIP and result is not STOP and bool(result)
    return predicate


class Iter(object):
    """Lazily apply a subspec to each target item.

    Operations return new Iter specs, so an existing pipeline can safely be
    reused. Use ``all()`` to collect a list or ``first()`` to select an item.
    SKIP omits an item and STOP terminates iteration.
    """
    def __init__(self, subspec=T, sentinel=STOP):
        self.subspec = subspec
        self.sentinel = sentinel
        self._operations = ()

    def _add(self, name, *args, **kwargs):
        result = type(self)(self.subspec, sentinel=self.sentinel)
        result._operations = self._operations + ((name, args, kwargs),)
        return result

    def map(self, subspec):
        """Apply another subspec to each item."""
        return self._add('map', subspec)

    def filter(self, key=T):
        """Keep items whose key spec evaluates to a truthy value."""
        return self._add('filter', key)

    def chunked(self, size, **kwargs):
        """Yield lists containing up to size items (optionally padded)."""
        return self._add('chunked', size, **kwargs)

    def windowed(self, size):
        """Yield overlapping, fixed-size tuples."""
        return self._add('windowed', size)

    def flatten(self):
        """Flatten one level of iterables."""
        return self._add('flatten')

    def unique(self, key=T):
        """Keep the first item for each distinct key, in input order."""
        return self._add('unique', key)

    def slice(self, *args):
        """Slice the stream using itertools.islice semantics."""
        return self._add('slice', *args)

    def limit(self, count):
        """Take at most count items."""
        return self.slice(count)

    def takewhile(self, key=T):
        """Take items while key is truthy."""
        return self._add('takewhile', key)

    def dropwhile(self, key=T):
        """Drop items until key first becomes false."""
        return self._add('dropwhile', key)

    def all(self):
        """Return a spec collecting this stream into a list."""
        return (self, list)

    def first(self, key=T, default=None):
        """Return a spec selecting the first matching item."""
        return (self, First(key=key, default=default))

    def glomit(self, target, scope):
        iterator = _map(_iterate(target, scope), self.subspec, scope,
                        self.sentinel)
        for name, args, kwargs in self._operations:
            if name == 'map':
                iterator = _map(iterator, args[0], scope, self.sentinel)
            elif name == 'filter':
                iterator = filter(_predicate(args[0], scope), iterator)
            elif name == 'chunked':
                iterator = chunked_iter(iterator, *args, **kwargs)
            elif name == 'windowed':
                iterator = windowed_iter(iterator, *args)
            elif name == 'flatten':
                iterator = itertools.chain.from_iterable(iterator)
            elif name == 'unique':
                spec = args[0]
                # Bind spec now, rather than closing over the loop variable.
                key = lambda value, spec=spec: scope[glom](value, spec, scope)
                iterator = unique_iter(iterator, key=key)
            elif name == 'slice':
                iterator = itertools.islice(iterator, *args)
            elif name == 'takewhile':
                iterator = itertools.takewhile(_predicate(args[0], scope), iterator)
            elif name == 'dropwhile':
                iterator = itertools.dropwhile(_predicate(args[0], scope), iterator)
        return iterator

    def __repr__(self):
        result = 'Iter(%r)' % (self.subspec,)
        for name, args, kwargs in self._operations:
            parts = [repr(arg) for arg in args]
            parts.extend('%s=%r' % item for item in kwargs.items())
            result += '.%s(%s)' % (name, ', '.join(parts))
        return result


class First(object):
    """Select the first item with a truthy key spec, or return default."""
    def __init__(self, key=T, default=None):
        self.key = key
        self.default = default

    def glomit(self, target, scope):
        predicate = _predicate(self.key, scope)
        for item in _iterate(target, scope):
            if predicate(item):
                return item
        return self.default

    def __repr__(self):
        return 'First(key=%r, default=%r)' % (self.key, self.default)
